function selectRoute(route){rememberMatchDraft();posterPreviewVersion++;weeklyPreviewVersion++;if(['roster','studio','pitch'].includes(route)&&!state.currentId){toast('Önce bir maç kaydı oluştur.');route='matches';}if(route==='roster'&&state.rosterFilterMatchId!==state.currentId){const m=activeMatch();state.rosterPoolGroups=m?.groupId?[m.groupId]:[];state.rosterFilterMatchId=state.currentId;state.rosterQuery='';}if(route==='pitch'&&state.route!=='pitch'){state.pitchMode='match';state.pitchSelectedId=null;}state.pitchContext=null;state.route=route;state.modal=null;render();if(route==='live')loadLiveClock();window.scrollTo(0,0);}
function btn(label,action,cls='btn-primary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`}
